package devtools

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"logplatform/pkg/personnames"
	"net/http"
	"strconv"
	"strings"
)

// Include underscore-prefixed shared chunks generated by the UI bundler.
//
//go:embed all:assets
var uiFS embed.FS

func Routes(tokens *TokenStore, tools *ToolService) *http.ServeMux {
	tools.actions = tokens
	mux := http.NewServeMux()
	tools.registerWorkLoopBackground(mux)
	writeJSON := func(w http.ResponseWriter, status int, value any) {
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		w.WriteHeader(status)
		_ = json.NewEncoder(w).Encode(value)
	}
	assets, err := fs.Sub(uiFS, "assets/app")
	if err == nil {
		mux.Handle("GET /assets/", http.FileServer(http.FS(assets)))
	}
	mux.Handle("/mcp", NewMCPHandler(tokens, tools))
	registerWorkflowSkillRoutes(mux, tools, writeJSON)
	mux.HandleFunc("GET /api/tools", func(w http.ResponseWriter, r *http.Request) {
		rows := []map[string]any{}
		for _, t := range tools.Tools() {
			rows = append(rows, map[string]any{"name": t.Name, "title": t.Title, "scope": t.Scope, "read_only": t.Annotations["readOnlyHint"]})
		}
		writeJSON(w, 200, rows)
	})
	mux.HandleFunc("GET /api/health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]any{"ok": true, "transport": "streamable-http", "tools": toolNames(tools.Tools())})
	})
	mux.HandleFunc("GET /api/tokens", func(w http.ResponseWriter, r *http.Request) {
		type tokenView struct {
			AccessToken
			OwnerName string `json:"owner_name,omitempty"`
		}
		rows := []tokenView{}
		names := personnames.FromRequest(r)
		for _, t := range tokens.List() {
			if r.Header.Get("X-Role") == "admin" || t.Owner == r.Header.Get("X-User") {
				rows = append(rows, tokenView{t, names.Name(t.Owner)})
			}
		}
		writeJSON(w, http.StatusOK, rows)
	})
	mux.HandleFunc("POST /api/tokens", func(w http.ResponseWriter, r *http.Request) {
		var req CreateTokenRequest
		if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 32<<10)).Decode(&req); err != nil {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求格式错误"})
			return
		}
		req.Owner = r.Header.Get("X-User")
		req.Scopes = normalizeValues(req.Scopes, len(allowedScopes))
		if (contains(req.Scopes, "resources:read") || contains(req.Scopes, "resources:write")) && r.Header.Get("X-Role") != "admin" {
			writeJSON(w, 403, map[string]string{"error": "资源接入权限仅管理员可授权"})
			return
		}
		if contains(req.Scopes, "apidocs:write") && r.Header.Get("X-Role") != "admin" {
			writeJSON(w, 403, map[string]string{"error": "接口文档上报权限仅管理员可授权"})
			return
		}
		if contains(req.Scopes, "arthas:read") && r.Header.Get("X-Role") != "admin" {
			writeJSON(w, 403, map[string]string{"error": "Java 诊断权限仅管理员可授权"})
			return
		}
		token, raw, err := tokens.Create(req)
		if err != nil {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
			return
		}
		token.Hash = ""
		writeJSON(w, http.StatusCreated, map[string]any{"token": token, "secret": raw})
	})

	for _, method := range []string{"PUT", "DELETE"} {
		path := "/api/tokens/{id}"
		if method == "DELETE" {
			path += "/record"
		}
		mux.HandleFunc(method+" "+path, func(w http.ResponseWriter, r *http.Request) {
			var req UpdateTokenRequest
			decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 32<<10))
			decoder.DisallowUnknownFields()
			if decoder.Decode(&req) != nil {
				writeJSON(w, 400, map[string]string{"error": "令牌参数格式错误"})
				return
			}
			value, err := tokens.maintainToken(r.PathValue("id"), r.Header.Get("X-User"), r.Header.Get("X-Role") == "admin", &req, method == "DELETE")
			if err != nil {
				writeJSON(w, 409, map[string]string{"error": err.Error()})
				return
			}
			writeJSON(w, 200, value)
		})
	}
	mux.HandleFunc("DELETE /api/tokens/{id}", func(w http.ResponseWriter, r *http.Request) {
		allowed := false
		for _, t := range tokens.List() {
			if t.ID == r.PathValue("id") && (r.Header.Get("X-Role") == "admin" || t.Owner == r.Header.Get("X-User")) {
				allowed = true
			}
		}
		if !allowed {
			writeJSON(w, 403, map[string]string{"error": "不能撤销其他账号的令牌"})
			return
		}
		if err := tokens.Revoke(strings.TrimSpace(r.PathValue("id"))); err != nil {
			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
			return
		}
		writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
	})
	mux.HandleFunc("GET /api/audit", func(w http.ResponseWriter, r *http.Request) {
		limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
		allowed := tokens.auditTokenIDs(r.Header.Get("X-User"), r.Header.Get("X-Role") == "admin")
		rows := []AuditEvent{}
		for _, a := range tokens.AuditEvents(limit) {
			if r.Header.Get("X-Role") == "admin" || allowed[a.TokenID] || a.Actor != "" && a.Actor == r.Header.Get("X-User") {
				rows = append(rows, a)
			}
		}
		writeJSON(w, http.StatusOK, rows)
	})
	mux.HandleFunc("GET /ui", func(w http.ResponseWriter, r *http.Request) {
		body, err := uiFS.ReadFile("assets/app/devtools.html")
		if err != nil {
			http.Error(w, fmt.Sprint(err), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write(body)
	})
	return mux
}
